#include <bits/stdc++.h>
using namespace std;constexpr int N=5730,D=17;int16_t X[N][D];int ord[N],q[D];uint16_t B[12];long long hist[14]{},seen=0,kept=0;ofstream fo,fb;
void eval(){seen++;int c=0;for(int k=0;k<N;k++){int i=ord[k],dot=2*q[16]*X[i][16];for(int j=0;j<16;j++)if(q[j])dot+=q[j]*X[i][j];if(dot>144){if(c==12){c=13;break;}B[c++]=i;}}hist[c]++;if(c<=12){for(int i=c;i<12;i++)B[i]=65535;int16_t w[D];for(int i=0;i<D;i++)w[i]=q[i];fo.write((char*)w,sizeof(w));fb.write((char*)B,sizeof(B));kept++;if(c==0){cout<<"POTENTIAL FREE"<<endl;fo.flush();fb.flush();exit(0);}}}
void choose(int start,int dep,int *p){if(dep==6){for(int mask=0;mask<128;mask++){memset(q,0,sizeof(q));for(int j=0;j<6;j++)q[p[j]]=(mask>>j&1)?-6:6;q[16]=(mask>>6&1)?-6:6;eval();}return;}for(int j=start;j<=16-(6-dep);j++){p[dep]=j;choose(j+1,dep+1,p);}}
int main(){ifstream f("search17_twice_source.bin",ios::binary);f.read((char*)X,sizeof(X));if(!f)return 1;iota(ord,ord+N,0);mt19937 r(170726);shuffle(ord,ord+N,r);fo.open("search17_full_tier_Q.bin",ios::binary);fb.open("search17_full_tier_B.bin",ios::binary);int p[6];choose(0,0,p);cout<<"total "<<seen<<" kept "<<kept<<" hist ";for(int k=0;k<14;k++)cout<<k<<":"<<hist[k]<<" ";cout<<endl;}
